3	  useEffect,
4	  useRef,
5	  useState,
6	  type Dispatch,
7	  type SetStateAction,
8	} from "react";
9	import { flushSync } from "react-dom";
10	import type { PlateEditor } from "platejs/react";
11	import { type AnnotationComposerPayload } from "@symbiot/ui/components/AnnotationComposer";
12	
13	import {
14	  applyAnnotation,
15	  hasValidSelection,
16	  type AppliedAnnotation,
17	} from "../utils/applyAnnotation.ts";
18	import { applyTaskToggle, removeTaskToggle } from "../utils/applyTaskToggle.ts";
19	import { hasAnnotationMark, removeAnnotationMark } from "../utils/removeAnnotationMark.ts";
20	
21	import { pruneRemovedAnnotation, snapshotOf } from "./ReviewEditorPrune.tsx";
22	import { type AnnotationMaps, type PruneSetters } from "./ReviewEditorState.tsx";
23	import {
24	  type AnnotationHandleKind,
25	  type EditorSnapshot,
26	  type ReviewEditorHandle,
27	} from "./ReviewEditorTypes.tsx";
28	
29	/** Authoring flow currently in flight, waiting for the composer's Save. */
30	export type PendingAuthoring =
31	  | { kind: "comment"; applied: AppliedAnnotation }
32	  | { kind: "insertion"; applied: AppliedAnnotation }
33	  | { kind: "replacement"; applied: AppliedAnnotation };
