49	/** Save the composer payload into the insertion maps. */
50	export const saveInsertionBody = (
51	  setters: PruneSetters,
52	  id: string,
53	  anchorText: string,
54	  payload: AnnotationComposerPayload
55	): void => {
56	  setters.setInsertionNewTexts((prev) => new Map(prev).set(id, payload.body));
57	  if (payload.images.length > 0) {
58	    setters.setInsertionImages((prev) => new Map(prev).set(id, payload.images));
59	  }
60	  setters.setInsertionOriginalTexts((prev) => new Map(prev).set(id, anchorText));
61	};
62	
63	/** Save the composer payload into the replacement maps. */
64	export const saveReplacementBody = (
65	  setters: PruneSetters,
66	  id: string,
67	  anchorText: string,
68	  payload: AnnotationComposerPayload
69	): void => {
70	  setters.setReplacementTexts((prev) => new Map(prev).set(id, payload.body));
71	  if (payload.images.length > 0) {
72	    setters.setReplacementImages((prev) => new Map(prev).set(id, payload.images));
73	  }
74	  setters.setReplacementOriginalTexts((prev) => new Map(prev).set(id, anchorText));
75	};
76	
77	/** Toolbar button click handlers wired to {@link applyAnnotation}. */
78	export interface ToolbarHandlers {
79	  onCommentClick: () => void;
80	  onInsertClick: () => void;
81	  onReplaceClick: () => void;
82	  onDeleteClick: () => void;
83	  /** Dispatch the matching handler by kind; used by host-side hotkeys. */
84	  triggerAnnotation: (kind: AnnotationHandleKind) => void;
85	}
86	
87	/** Dependencies passed into the toolbar-handlers hook. */
88	export interface ToolbarHandlerDeps {
89	  editor: PlateEditor;
90	  maps: AnnotationMaps;
91	  setters: PruneSetters;
92	  setPending: Dispatch<SetStateAction<PendingAuthoring | null>>;
93	  onChange?: (snapshot: EditorSnapshot) => void;
94	}
95	
96	/** Toolbar click handlers — extracted so `ReviewEditor` stays under the line-count cap. */
97	export const useToolbarHandlers = ({
98	  editor,
99	  maps,
100	  setters,
101	  setPending,
102	  onChange,
103	}: ToolbarHandlerDeps): ToolbarHandlers => {
104	  const openComposer = useCallback(
105	    (kind: "comment" | "insertion" | "replacement"): void => {
106	      const applied = applyAnnotation(editor, kind);
107	      if (applied === null) return;
108	      setPending({ kind, applied });
109	    },
110	    [editor, setPending]
111	  );
112	  const onCommentClick = useCallback((): void => openComposer("comment"), [openComposer]);
113	  const onInsertClick = useCallback((): void => openComposer("insertion"), [openComposer]);
114	  const onReplaceClick = useCallback((): void => openComposer("replacement"), [openComposer]);
115	  const onDeleteClick = useCallback((): void => {
116	    const applied = applyAnnotation(editor, "deletion");
117	    if (applied === null) {
118	      onChange?.(snapshotOf(editor, maps));
119	      return;
120	    }
121	    setters.setSuggestionOriginalTexts((prev) => new Map(prev).set(applied.id, applied.anchorText));
122	  }, [editor, maps, onChange, setters]);
123	  const triggerAnnotation = useCallback(
124	    (kind: AnnotationHandleKind): void => {
125	      if (kind === "comment") onCommentClick();
126	      else if (kind === "insertion") onInsertClick();
127	      else if (kind === "replacement") onReplaceClick();
128	      else onDeleteClick();
129	    },
130	    [onCommentClick, onInsertClick, onReplaceClick, onDeleteClick]
131	  );
132	  return { onCommentClick, onInsertClick, onReplaceClick, onDeleteClick, triggerAnnotation };
133	};
134	
135	/** Wire up the imperative `ReviewEditorHandle` and surface it through `onReady`. */
136	export const useReadyHandle = (
137	  editor: PlateEditor,
138	  maps: AnnotationMaps,
139	  removeAnnotation: ReviewEditorHandle["removeAnnotation"],
140	  updateAnnotation: ReviewEditorHandle["updateAnnotation"],
141	  triggerAnnotation: ReviewEditorHandle["triggerAnnotation"],
142	  onReady?: (h: ReviewEditorHandle) => void
143	): void => {
144	  useEffect(() => {
145	    onReady?.({
146	      hasValidSelection: () => hasValidSelection(editor),
147	      triggerAnnotation,
148	      getValue: () => editor.children,
149	      getCommentBodies: () => new Map(maps.bodies),
150	      getCommentImages: () => new Map(maps.images),
151	      getCommentOriginalTexts: () => new Map(maps.commentOriginalTexts),
152	      getSuggestionOriginalTexts: () => new Map(maps.suggestionOriginalTexts),
153	      getInsertionNewTexts: () => new Map(maps.insertionNewTexts),
154	      getInsertionImages: () => new Map(maps.insertionImages),
155	      getInsertionOriginalTexts: () => new Map(maps.insertionOriginalTexts),
156	      getReplacementTexts: () => new Map(maps.replacementTexts),
157	      getReplacementImages: () => new Map(maps.replacementImages),
158	      getReplacementOriginalTexts: () => new Map(maps.replacementOriginalTexts),
159	      removeAnnotation,
160	      updateAnnotation,
161	    });
162	  }, [editor, maps, removeAnnotation, updateAnnotation, triggerAnnotation, onReady]);
163	};
164	
165	/**
166	 * Set `id`'s images when non-empty, drop the key when empty so the map keeps its
167	 * "absent key ⇒ no images" shape (the add path never stores empty arrays). Returns
168	 * the same map reference when nothing changes.
169	 */
170	const withImages = (
171	  map: Map<string, string[]>,
172	  id: string,
173	  images: string[]
174	): Map<string, string[]> => {
175	  if (images.length > 0) return new Map(map).set(id, images);
176	  if (!map.has(id)) return map;
177	  const next = new Map(map);
178	  next.delete(id);
179	  return next;
180	};
181	
182	/** The body + image maps + their setters for one body-bearing kind. */
183	interface UpdateTarget {
184	  body: Map<string, string>;
185	  images: Map<string, string[]>;
186	  setBody: PruneSetters["setBodies"];
187	  setImages: PruneSetters["setImages"];
188	}
189	
190	const updateTarget = (
191	  kind: "comment" | "insertion" | "replacement",
192	  current: AnnotationMaps,
193	  setters: PruneSetters
194	): UpdateTarget => {
195	  if (kind === "comment") {
196	    return {
197	      body: current.bodies,
198	      images: current.images,
199	      setBody: setters.setBodies,
200	      setImages: setters.setImages,
201	    };
202	  }
203	  if (kind === "insertion") {
204	    return {
205	      body: current.insertionNewTexts,
206	      images: current.insertionImages,
207	      setBody: setters.setInsertionNewTexts,
208	      setImages: setters.setInsertionImages,
209	    };
210	  }
211	  return {
212	    body: current.replacementTexts,
213	    images: current.replacementImages,
214	    setBody: setters.setReplacementTexts,
215	    setImages: setters.setReplacementImages,
216	  };
217	};
218	
219	/**
220	 * Replace the body + images of an existing body-bearing annotation in place.
221	 *
222	 * Mirrors {@link pruneRemovedAnnotation}'s shape (reads `current` so existence is
223	 * checked atomically) but writes instead of deletes. Only the text + image maps
224	 * for `id` change; `*OriginalTexts` and the Plate mark are left alone so the
225	 * anchor + drift baseline survive the edit. No-op when `id` is unknown, which
226	 * stops a stale edit from resurrecting a removed annotation. Persistence flows
227	 * through the host's existing maps-change effect — unlike removal there is no
228	 * Plate-value mutation to capture, so no explicit `onChange` is needed here.
229	 */
230	export const updateAnnotationMaps = (
231	  kind: "comment" | "insertion" | "replacement",
232	  id: string,
233	  body: string,
234	  images: string[],
235	  current: AnnotationMaps,
236	  setters: PruneSetters
237	): void => {
238	  const target = updateTarget(kind, current, setters);
239	  if (!target.body.has(id)) return;
240	  target.setBody(new Map(target.body).set(id, body));
241	  target.setImages(withImages(target.images, id, images));
242	};
243	
244	/**
245	 * Memoized `removeAnnotation` handle method: clears the Plate mark, prunes every
246	 * map for the id, and pushes a fresh snapshot. Extracted (like {@link useReadyHandle})
247	 * so `ReviewEditor` stays under the per-function line cap.
248	 */
249	export const useRemoveAnnotation = (
250	  editor: PlateEditor,
251	  maps: AnnotationMaps,
252	  setters: PruneSetters,
253	  onChange?: (snapshot: EditorSnapshot) => void
254	): ReviewEditorHandle["removeAnnotation"] =>
255	  useCallback(
256	    (kind, id) => {
257	      if (kind === "task") {
258	        removeTaskToggle(editor, id);
259	        onChange?.(snapshotOf(editor, maps));
260	        return;
261	      }
262	      removeAnnotationMark(editor, kind, id);
263	      const next = pruneRemovedAnnotation(kind, id, maps, setters);
264	      onChange?.(snapshotOf(editor, next));
265	    },
266	    [editor, maps, onChange, setters]
267	  );
268	
269	/**
270	 * Memoized task-checkbox toggle handler for {@link TaskToggleContext}. Applies
271	 * the toggle to the editor value (see `applyTaskToggle`) and re-emits the
272	 * snapshot so the host persists the new `checked` + `task_<id>` marks.
273	 */
274	export const useTaskToggle = (
275	  editor: PlateEditor,
276	  maps: AnnotationMaps,
277	  onChange?: (snapshot: EditorSnapshot) => void
278	): ((element: unknown) => void) =>
279	  useCallback(
280	    (element) => {
281	      applyTaskToggle(editor, element);
282	      onChange?.(snapshotOf(editor, maps));
283	    },
284	    [editor, maps, onChange]
285	  );
286	
287	/**
288	 * Memoized `updateAnnotation` handle method bound to the current maps + setters.
289	 * Extracted (like {@link useReadyHandle}) so `ReviewEditor` stays under the
290	 * per-function line cap. Persistence flows through the host's maps-change effect.
291	 */
292	export const useUpdateAnnotation = (
293	  maps: AnnotationMaps,
294	  setters: PruneSetters
295	): ReviewEditorHandle["updateAnnotation"] =>
296	  useCallback(
297	    (kind, id, body, images) => updateAnnotationMaps(kind, id, body, images, maps, setters),
298	    [maps, setters]
299	  );
300	
301	/** Annotation handle kinds that route through the composer. */
302	export type ComposerKind = PendingAuthoring["kind"];
303	
304	/** Dispatch the composer payload to the matching map saver. */
305	export const dispatchComposerSave = (
306	  pending: PendingAuthoring,
307	  payload: AnnotationComposerPayload,
308	  setters: PruneSetters
309	): void => {
310	  const { id, anchorText } = pending.applied;
311	  if (pending.kind === "comment") {
312	    saveCommentBody(setters, id, anchorText, payload);
313	    return;
314	  }
315	  if (pending.kind === "insertion") {
316	    saveInsertionBody(setters, id, anchorText, payload);
317	    return;
318	  }
319	  saveReplacementBody(setters, id, anchorText, payload);
320	};
321	
322	/**
323	 * Roll back the eagerly-applied annotation mark when the composer is cancelled.
324	 * Pattern A applies the mark on open, so every cancel route (button, Escape,
325	 * overlay) must remove it or the selection stays highlighted with no body. No
326	 * map pruning is needed: a body is only stored on save, so the cancelled id
327	 * never entered the annotation maps. Mirrors {@link dispatchComposerSave}.
328	 */
329	export const dispatchComposerCancel = (
330	  pending: PendingAuthoring | null,
331	  editor: PlateEditor,
332	  maps: AnnotationMaps,
333	  onChange?: (snapshot: EditorSnapshot) => void
334	): void => {
335	  if (pending === null) return;
336	  removeAnnotationMark(editor, pending.kind, pending.applied.id);
337	  onChange?.(snapshotOf(editor, maps));
338	};
339	
340	/** Pending composer state plus its save / cancel handlers. */
341	export interface ComposerController {
342	  /** Authoring flow awaiting the composer's Save, or `null` when the composer is closed. */
343	  pending: PendingAuthoring | null;
344	  /** Opens the composer for a freshly-applied annotation; wired to {@link useToolbarHandlers}. */
345	  setPending: Dispatch<SetStateAction<PendingAuthoring | null>>;
346	  /** Persist the composer payload and close. */
347	  onComposerSave: (payload: AnnotationComposerPayload) => void;
348	  /** Close without saving; rolls the eager mark back synchronously in the dismiss event. */
349	  onComposerCancel: () => void;
350	}
351	
352	/**
353	 * Temporary diagnostic (symbiot#231): right after the synchronous cancel commit, record whether
354	 * the model was cleaned vs. what the DOM still shows, plus the focused element, on `window.__diag`.
355	 * The failing BDD step reads it back. Revert with the step-side instrumentation once confirmed.
356	 */
357	const recordCancelDiag = (editor: PlateEditor, pending: PendingAuthoring): void => {
358	  if (typeof document === "undefined") return;
359	  const w = window as unknown as { __diag?: unknown[] };
360	  const log = (w.__diag ??= []);
361	  const editorRoot = document.querySelector('[data-testid="editor-root"]');
362	  const snapshot = (ev: string): Record<string, unknown> => {
363	    const active = document.activeElement;
364	    return {
365	      ev,
366	      id: pending.applied.id,
367	      modelClean: !hasAnnotationMark(editor, pending.kind, pending.applied.id),
368	      domCount: document.querySelectorAll(`[data-testid="annotation-${pending.kind}"]`).length,
369	      activeTag: active ? active.tagName : null,
370	      activeTestId: active ? active.getAttribute("data-testid") : null,
371	      editorHasFocus: active !== null && editorRoot !== null && editorRoot.contains(active),
372	    };
373	  };
374	  log.push(snapshot("cancel"));
375	  // Focus-theory probe (symbiot#236): re-snapshot after the dismiss event settles and Radix
376	  // restores focus, to reveal WHERE focus lands per route (overlay click vs Cancel/Escape).
377	  setTimeout(() => log.push(snapshot("cancel+tick")), 0);
378	};
379	
380	/**
381	 * Own the inline composer's `pending` state and its save / cancel handlers.
382	 *
383	 * The eager "Pattern A" mark is rolled back **synchronously inside the cancel
384	 * event**, before the close commits and Radix's modal focus-restoration runs.
385	 * A deferred rollback (post-commit effect) races that focus restoration on the
386	 * overlay-dismiss route under CI load and intermittently leaves the highlight
387	 * behind (symbiot#231); running it in the handler closes the race.
388	 *
389	 * Save and cancel are already separate handlers: a save closes the dialog
390	 * programmatically (`open` → false), which does NOT fire Radix `onOpenChange`,
391	 * so it never reaches {@link onComposerCancel}; only genuine dismisses (button /
392	 * Escape / overlay click) do. `savedRef` still guards the rollback so that even
393	 * if a controlled close were to surface through `onOpenChange`, a just-saved mark
394	 * is kept; it is cleared whenever a fresh composer opens so a prior save never
395	 * suppresses the next cancel. `pendingRef` mirrors `pending` so the handler rolls
396	 * back the CURRENT id even when Radix invokes the callback from a stale render.
397	 * Extracted (like {@link useRemoveAnnotation}) so `ReviewEditor` stays under the
398	 * per-function line cap.
399	 */
400	export const useComposerController = (
401	  editor: PlateEditor,
402	  maps: AnnotationMaps,
403	  setters: PruneSetters,
404	  onChange?: (snapshot: EditorSnapshot) => void
405	): ComposerController => {
406	  const [pending, setPending] = useState<PendingAuthoring | null>(null);
407	  const pendingRef = useRef<PendingAuthoring | null>(null);
408	  const savedRef = useRef(false);
409	
410	  useEffect(() => {
411	    pendingRef.current = pending;
412	    if (pending !== null) savedRef.current = false;
413	  }, [pending]);
414	
415	  const onComposerSave = useCallback(
416	    (payload: AnnotationComposerPayload): void => {
417	      const { current } = pendingRef;
418	      if (current === null) return;
419	      dispatchComposerSave(current, payload, setters);
420	      savedRef.current = true;
421	      setPending(null);
422	    },
423	    [setters]
424	  );
425	
426	  const onComposerCancel = useCallback((): void => {
427	    if (savedRef.current) {
428	      savedRef.current = false;
429	      return;
430	    }
431	    const { current } = pendingRef;
432	    if (current === null) {
433	      setPending(null);
434	      return;
435	    }
436	    // Close the composer and roll the eager mark back in one synchronous commit. A React
437	    // re-render/remount does NOT clear the highlight on the blurred overlay-dismiss route
438	    // (symbiot#231 __diag: modelClean=true, domCount=1, editor blurred) — slate-react won't
439	    // reconcile the cleaned value into the blurred editor's DOM. Replacing the value with a
440	    // fresh array forces it to rebuild every leaf from the already-cleaned children.
441	    // eslint-disable-next-line @eslint-react/dom-no-flush-sync, n/no-sync -- synchronous commit before Radix focus restoration (symbiot#231)
442	    flushSync(() => {
443	      setPending(null);
444	      dispatchComposerCancel(current, editor, maps, onChange);
445	      editor.tf.setValue([...editor.children]);
446	    });
447	    recordCancelDiag(editor, current);
448	  }, [editor, maps, onChange]);
449	
450	  return { pending, setPending, onComposerSave, onComposerCancel };
451	};
