10	 * tag with the given Tailwind class string. Used by `CommentLeaf`,
11	 * `DeletionLeaf`, `InsertionLeaf`, and `ReplacementLeaf` so the shared
12	 * `(attributes, children) → <tag className>` shape lives in one place. Leaves
13	 * with operation-aware rendering (e.g. `DiffLeaf`) opt out of the factory.
14	 *
15	 * `testId` stamps a `data-testid` on the rendered element so Playwright-BDD
16	 * specs can locate the highlight by kind (the suite forbids class/role
17	 * selectors — see `docs/08-testing.md#playwright-bdd-selectors`).
18	 *
19	 * @example
20	 *   export const CommentLeaf = createAnnotationLeaf(
21	 *     "mark",
22	 *     "text-anno-comment bg-anno-comment/10 rounded-sm px-0.5",
23	 *     "CommentLeaf",
24	 *     "annotation-comment",
25	 *   );
26	 */
27	export const createAnnotationLeaf = (
28	  tag: ElementType,
29	  className: string,
30	  displayName: string,
31	  testId: string
32	): React.FC<AnnotationLeafProps> => {
33	  const Tag = tag;
34	  const AnnotationLeaf = ({ attributes, children }: AnnotationLeafProps): React.ReactElement => (
35	    <Tag {...attributes} className={className} data-testid={testId}>
36	      {children}
37	    </Tag>
38	  );
39	  AnnotationLeaf.displayName = displayName;
40	  return AnnotationLeaf;
41	};
